// =========================================================================
// Title: Squished Image
// Based on: "Squished Coordinates" by pyBlob
//           https://www.shadertoy.com/view/W3KcWd
//
// License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported
//          (CC BY-NC-SA 3.0) - https://creativecommons.org/licenses/by-nc-sa/3.0/
//
// Note: Adapted and modified for the "Surfaces Explorer" engine.
//       Only the DEFORMATION of the original: no red axes, no orange
//       circle, no white veil. The image keeps its full saturation and is
//       only animated.
// =========================================================================
//
// WHAT IT DOES: the coordinate is squashed along one axis and stretched
// along the perpendicular one. The matrix has determinant 1, so the area is
// preserved: the image deforms without swelling or shrinking.
// The axis rotates over time and the image seems to sway.
//
// TWO CONSTRAINTS OF THE SHADERTOY BRANCH, each of which already caused an error:
//  1. the A..F sliders and t can NOT be used here: the engine declares them
//     as LOCAL variables of getCustomColor(), while mainImage() is a
//     separate function -> "'A' : undeclared identifier";
//  2. no MODULE-level declarations (const, global variables): with two
//     meshes using this script the file would contain two copies of them
//     -> "'SQUISH' : redefinition". The engine renames per mesh only the
//     known symbols (iTime, mainImage, iChannelN...), not the user's names.
// That is why the parameters live INSIDE mainImage: there the scope is per
// function and each mesh has its own copy.

void mainImage(out vec4 Q, vec2 U)
{
    // --- PARAMETERS (edit here) ---
    float squish = 0.35;   // how much it squashes (0 = image still and intact)
    float speed  = 0.2;    // rotation speed of the axis

    // Centred coordinate: in the Shadertoy branch iResolution is 1024,
    // so V runs roughly over [-0.5, 0.5].
    vec2 V = U / iResolution.xy - 0.5;

    float a = iTime * speed;   // angle of the deformation axis

    // Determinant-1 deformation: exp(-e) on one axis, exp(+e) on the other.
    // It is the same matrix as the original, written out in full.
    float c2 = cos(a) * cos(a);
    float s2 = sin(a) * sin(a);
    float sh = -sin(2.0 * a) * sinh(squish);
    V = mat2(c2 * exp(-squish) + s2 * exp(squish), sh,
             sh, c2 * exp(squish) + s2 * exp(-squish)) * V;

    // Direct sampling, no mip bias: the image stays sharp.
    // +0.5 brings the coordinate back to [0,1].
    Q = texture(iChannel0, V + 0.5);
}
